import {planetOf} from './planet-gravity.mjs';
import {transactionLedger,compareTransaction} from './simulation/transaction-audit.mjs';
import {createGlassHouse} from './tile-physics/glass-house.mjs';
import * as inertia from './glass-house/inertia-layers.mjs';
import {createRanchPhysics,selectRanchCollisionMeshes} from './tile-physics/ranch-adapter.mjs?v=3';
import {PROFILES} from './tile-physics/world.mjs';
// Optional transaction: real-time physics, exact Cancel, explicit Return.
export function createMotionControls({container,getActive,beforeBegin}){
 const section=document.createElement('section');section.className='tile-motion-controls';section.innerHTML='<h3>Tile motion · experimental</h3><p>Hold a tile for half a second to pick it up. Drag to move it; release to drop. Escape or Cancel restores the scene.</p><label>Mode <select aria-label="Tile motion mode"><option value="physics">Physical experiment</option><option value="glass">Glass House · reassemble</option></select></label><label>Tile <select aria-label="Motion tile"></select></label><label>Gravity <select aria-label="Tile gravity"><option value="tile">Tile planet (automatic)</option><option value="earth">Earth override</option><option value="moon">Moon override</option><option value="mars">Mars override</option></select></label><label>Response <select aria-label="Motion response"><option value="panic">Panic</option><option value="carry-on">Carry on</option></select></label><div class="motion-actions"><button type="button" data-action="move" aria-pressed="false">Move tile</button><button type="button" data-action="drop" disabled>Drop</button><button type="button" data-action="lift">Lift</button><button type="button" data-action="tilt">Tilt</button><button type="button" data-action="return" disabled>Return</button><button type="button" data-action="cancel" disabled>Cancel</button></div><p role="status" class="motion-status">Normal simulation</p>';
 container.append(section);const mode=section.querySelector('[aria-label="Tile motion mode"]');const tile=section.querySelector('[aria-label="Motion tile"]'),gravity=section.querySelector('[aria-label="Tile gravity"]'),response=section.querySelector('[aria-label="Motion response"]'),status=section.querySelector('.motion-status');let instance=null,adapter=null,glass=null,glassPose=null,glassHome=null,glassMotion=null,tileId=null,returning=false,returnAge=0,ledgerBefore=null,disabled=[],moveEnabled=false;
 function gravityLabel(){const a=getActive(),p=a?.assembly.plans.find(p=>p.id===tile.value),planet=planetOf({...p,...a?.recipe.tiles.find(t=>t.id===tile.value)});gravity.options[0].textContent=`Tile planet · ${planet[0].toUpperCase()+planet.slice(1)} (${Math.abs(PROFILES[planet].gravity[1])} m/s²)`;}
 tile.addEventListener('change',gravityLabel);
 function refresh(){const a=getActive();if(!a||a===instance||adapter||glass)return;instance=a;tile.replaceChildren(...a.assembly.plans.map((p,i)=>{const o=document.createElement('option');o.value=p.id;o.textContent='Tile '+(i+1);return o;}));gravityLabel();}
 function lock(on){if(on&&!disabled.length){disabled=[...document.querySelectorAll('#generate,#size,#complexity,#shape-open,#biodiversity,#horses,#cows,#goats,#chickens,#goatPlay,#playground,#arrival,#year-minutes,#season-cycle,#pause,#lighting,#season-toggle,#simulation-speed,#weather-mode')].map(e=>[e,e.disabled]);for(const [e]of disabled)e.disabled=true;}else if(!on){for(const [e,value]of disabled)e.disabled=value;disabled=[];}tile.disabled=mode.disabled=on;gravity.disabled=response.disabled=on||mode.value==='glass';for(const b of section.querySelectorAll('button'))b.disabled=b.dataset.action==='move'?mode.value==='glass'||returning:b.dataset.action==='drop'?!adapter||returning:['return','cancel'].includes(b.dataset.action)?!on:on&&returning;}
 function finish(message,cancelled=false){moveEnabled=false;section.querySelector('[data-action="move"]').setAttribute("aria-pressed","false");if(ledgerBefore){section.dataset.transactionAudit=JSON.stringify(compareTransaction(ledgerBefore,transactionLedger(instance.life.state),{cancelled}));ledgerBefore=null;}instance?.life.physics.setPresentationHidden(false);adapter?.dispose();glass?.dispose();adapter=null;glass=null;glassMotion=null;returning=false;lock(false);status.textContent=message;}
 function cancel(){moveEnabled=false;section.querySelector('[data-action=move]').setAttribute('aria-pressed','false');if(!adapter&&!glass)return;try{adapter?.cancel();glass?.cancel();finish('Cancelled · original scene and jobs restored',true);}catch(e){status.textContent='Restore failed: '+e.message;throw e;}}
 function begin(){refresh();if(adapter||glass)return;const a=getActive();if(!a||a.arrival&&!a.arrival.done)throw Error('Wait for arrival to finish');beforeBegin();instance=a;ledgerBefore=transactionLedger(a.life.state);tileId=tile.value;if(mode.value==='glass'){glass=createGlassHouse({root:a.group,tileObjects:a.tileObjects,entities:()=>a.life.physics.entities(),fixtures:()=>a.life.physics.fixtures(),inertia,radiusMetres:a.assembly.radiusMetres??Number(document.querySelector('#size').value)/2});const object=a.tileObjects.find(t=>t.id===tileId).object;glassHome={position:object.position.toArray().map(v=>v/.1),rotation:object.quaternion.toArray()};glassPose=structuredClone(glassHome);try{glass.begin(tileId);a.life.physics.setPresentationHidden(true);lock(true);}catch(e){glass.dispose();glass=null;throw e;}return;}const tileObjects=a.tileObjects.map(t=>({...t,collisionMeshes:selectRanchCollisionMeshes(t.object,a.assembly.plans.find(p=>p.id===t.id))}));if(tileObjects.some(t=>!t.collisionMeshes.length))throw Error('Tile collision geometry unavailable');adapter=createRanchPhysics({root:a.group,assembly:a.assembly,tileObjects,radiusMetres:a.assembly.radiusMetres??Number(document.querySelector('#size').value)/2,entities:()=>a.life.physics.entities(),fixtures:()=>a.life.physics.fixtures(),behavior:a.life.physics,snapshotBehavior:()=>a.life.snapshot(),restoreBehavior:s=>a.life.restore(s),profiles:Object.fromEntries(a.assembly.plans.map(p=>[p.id,PROFILES[p.id===tileId&&gravity.value!=='tile'?gravity.value:planetOf({...p,...a.recipe.tiles.find(t=>t.id===p.id)})]]))});try{adapter.begin(tileId,{response:response.value});a.life.physics.setPresentationHidden(true);lock(true);}catch(e){adapter.dispose();adapter=null;throw e;}}
 for(const b of section.querySelectorAll('button'))b.onclick=()=>{try{const action=b.dataset.action;if(action==='move'){moveEnabled=!moveEnabled;b.setAttribute('aria-pressed',String(moveEnabled));status.textContent=moveEnabled?'Drag the selected tile with mouse, pen, or one finger · release to drop':'Tile move off';return;}if(action==='drop'){drop();return;}if(action==='cancel'){cancel();return;}if(action==='return'){if(glass){glassMotion={from:structuredClone(glassPose),to:glassHome,time:0};}else{adapter.end();adapter.returnTile(tileId,1);}returning=true;returnAge=0;lock(true);status.textContent=glass?'Reassembling · day paused':'Returning · waiting for safe footing';return;}begin();if(adapter)adapter.grab(tileId);const f=glass?glassPose:adapter.world.tiles.get(tileId).frame;const move=(target)=>{if(glass)glassMotion={from:structuredClone(glassPose),to:target,time:0};else adapter.move(target,1);};if(action==='lift')move({position:[f.position[0],f.position[1]+1.5,f.position[2]],rotation:f.rotation});else{const angle=.12;move({position:f.position,rotation:[0,0,Math.sin(angle/2),Math.cos(angle/2)]});}status.textContent=action==='lift'?'Lifted · day paused':'Tilted · day paused';}catch(e){status.textContent=e.message;if(adapter||glass){try{cancel();}catch{}}}};
 mode.onchange=()=>{moveEnabled=false;section.querySelector('[data-action=move]').setAttribute('aria-pressed','false');lock(false);status.textContent="Normal simulation";section.querySelector('p').textContent=mode.value==='glass'?'Original Glass House spring animation on temporary copies. Return reassembles the scene.':'Hold a tile for half a second to pick it up. Drag to move it; release to drop. Escape or Cancel restores the scene.';};
 function drop(){if(!adapter)return;adapter.drop();status.textContent='Dropped · Return or Cancel to resume';}
 return {get longPressEnabled(){return !returning&&mode.value==='physics';},canGrab(id){return !returning&&mode.value==='physics'&&(!adapter||id===tileId);},get moveEnabled(){return moveEnabled&&!returning&&mode.value==='physics';},get selectedTile(){return tile.value;},startDrag(id,{select=false}={}){try{if(select&&!adapter&&!glass){refresh();tile.value=id;gravityLabel();}if(id!==tile.value)return null;begin();adapter.grab(id);const f=adapter.world.tiles.get(id).frame;status.textContent='Moving tile · release to drop';return structuredClone({position:f.position,rotation:f.rotation});}catch(e){status.textContent=e.message;return null;}},dragTo(pose,dt){try{adapter?.move(pose,dt);}catch(e){cancel();status.textContent=e.message;}},drop,get active(){return !!adapter||!!glass;},refresh,cancel,update(dt){if(!adapter&&!glass){refresh();return;}if(glass){try{if(glassMotion){glassMotion.time=Math.min(1,glassMotion.time+dt);const t=glassMotion.time,e=t*t*(3-2*t);glassPose={position:glassMotion.from.position.map((v,k)=>v+(glassMotion.to.position[k]-v)*e),rotation:glassMotion.from.rotation.map((v,k)=>v+(glassMotion.to.rotation[k]-v)*e)};const length=Math.hypot(...glassPose.rotation);glassPose.rotation=glassPose.rotation.map(v=>v/length);glass.move(glassPose);if(t===1){glassMotion=null;if(returning){glass.end();finish('Reassembled · simulation resumed');return;}}}glass.update(dt,{reduced:matchMedia('(prefers-reduced-motion: reduce)').matches});}catch(e){cancel();status.textContent='Presentation cancelled: '+e.message;}return;}try{adapter.update(dt);adapter.drainEvents();if(returning){returnAge+=dt;if(returnAge>20){cancel();status.textContent='Could not regain safe footing · original scene restored';return;}}const entityById=new Map(instance.life.physics.entities().map(e=>[e.bodyId,e]));section.dataset.physics=JSON.stringify(adapter.owned.map(id=>{const b=adapter.world.bodies.get(id);return {id,position:b.position,settled:b.settled,tileId:b.tileId,recovery:entityById.get(id)?.recovery};}));if(returning&&!adapter.owned.length&&![...adapter.world.tiles.values()].some(t=>t.motion)){finish('Returned · simulation resumed');}}catch(e){const message=e.message;cancel();status.textContent='Experiment cancelled: '+message;}},dispose(){cancel();section.remove();}};
}
